   768  /*
   769   * Initializes the session structure.
   770   * May perform one time minimal library initialization.
   771   * No MIB file processing is done via this call.
   772   */
   773  void
   774  snmp_sess_init(netsnmp_session * session)
   775  {
   776      _init_snmp();
   777
   778      /*
   779       * initialize session to default values
   780       */
   781
   782      memset(session, 0, sizeof(netsnmp_session));
   783      session->timeout = SNMP_DEFAULT_TIMEOUT;
   784      session->retries = SNMP_DEFAULT_RETRIES;
   785      session->version = SNMP_DEFAULT_VERSION;
   786      session->securityModel = SNMP_DEFAULT_SECMODEL;
   787      session->rcvMsgMaxSize = netsnmp_max_send_msg_size();
   788      session->sndMsgMaxSize = netsnmp_max_send_msg_size();
   789      session->flags |= SNMP_FLAGS_DONT_PROBE;
   790  }
